import{_ as t,o,c as i,a2 as r}from"./chunks/framework.CkKL3Me7.js";const u=JSON.parse('{"title":"VERA Roadmap — Financial Intelligence & Operational Visibility","description":"","frontmatter":{},"headers":[],"relativePath":"2026-03-19-roadmap-financial-intelligence.md","filePath":"2026-03-19-roadmap-financial-intelligence.md"}'),a={name:"2026-03-19-roadmap-financial-intelligence.md"};function n(s,e,l,d,c,h){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="vera-roadmap-—-financial-intelligence-operational-visibility" tabindex="-1">VERA Roadmap — Financial Intelligence &amp; Operational Visibility <a class="header-anchor" href="#vera-roadmap-—-financial-intelligence-operational-visibility" aria-label="Permalink to &quot;VERA Roadmap — Financial Intelligence &amp; Operational Visibility&quot;">​</a></h1><p><em>2026-03-19</em></p><h2 id="strategic-assessment" tabindex="-1">Strategic Assessment <a class="header-anchor" href="#strategic-assessment" aria-label="Permalink to &quot;Strategic Assessment&quot;">​</a></h2><p>VERA is already strong on <strong>input</strong> (time logging, project setup, allocations) and <strong>monitoring</strong> (morning summaries, proactive alerts, retainer burn tracking). Where it&#39;s thin is the <strong>output</strong> side — turning accumulated data into the financial intelligence that justifies the product&#39;s name (<em>Visible Efficiency Ratio Analytics</em>).</p><p>Every agency owner asks the same five questions, roughly in this order:</p><ol><li><strong>&quot;Are we profitable?&quot;</strong> — by client, by project, by person</li><li><strong>&quot;Who&#39;s busy and who&#39;s not?&quot;</strong> — utilization, not just allocation</li><li><strong>&quot;What will revenue look like next month?&quot;</strong> — forward projection</li><li><strong>&quot;Can I bill from this?&quot;</strong> — invoice-ready grouped exports</li><li><strong>&quot;What changed this week?&quot;</strong> — trends, not just today&#39;s snapshot</li></ol><p>VERA has the data to answer all five. None require schema changes — just new read endpoints and one cron job.</p><hr><h2 id="recommended-build-order" tabindex="-1">Recommended Build Order <a class="header-anchor" href="#recommended-build-order" aria-label="Permalink to &quot;Recommended Build Order&quot;">​</a></h2><h3 id="_1-utilization-report-—-get-utilization-report" tabindex="-1">1. Utilization Report — <code>get_utilization_report</code> <a class="header-anchor" href="#_1-utilization-report-—-get-utilization-report" aria-label="Permalink to &quot;1. Utilization Report — `get_utilization_report`&quot;">​</a></h3><p><strong>Why first:</strong> Utilization is the single most important metric in professional services. VERA already tracks <code>get_team_availability</code> (allocation-based capacity) but has no view of <strong>actual</strong> utilization: billable hours logged ÷ total available hours per person. Every agency owner, every PM, every week.</p><p><strong>What it does:</strong></p><ul><li>Period input (this week, this month, custom range)</li><li>Per-person: total hours logged, billable hours, non-billable hours, available hours (workdays × hours/day − holidays − PTO), utilization % (billable ÷ available), effective rate if owner</li><li>Team aggregate: average utilization, billable ratio, bench count (people under 50%)</li><li>Role-based: owners see dollars and rates, managers see percentages for their team, users see own row only</li></ul><p><strong>Data sources:</strong> <code>01. Time Entries</code>, <code>02. Projects</code> (is_billable), <code>03. Users</code>, <code>12. Company_Calendar</code>, <code>13. Rate_History</code> (for effective rate). All already read by existing endpoints.</p><p><strong>Effort:</strong> Medium. Pure read logic — no writes, no new sheets, no schema changes.</p><hr><h3 id="_2-client-profitability-—-get-client-profitability" tabindex="-1">2. Client Profitability — <code>get_client_profitability</code> <a class="header-anchor" href="#_2-client-profitability-—-get-client-profitability" aria-label="Permalink to &quot;2. Client Profitability — `get_client_profitability`&quot;">​</a></h3><p><strong>Why second:</strong> After &quot;who&#39;s busy,&quot; the next question is always &quot;which clients make us money.&quot; VERA tracks revenue (contract values, billing rates) and cost (rate history, liabilities) per project, but has no client-level rollup.</p><p><strong>What it does:</strong></p><ul><li>Per-client: total revenue (varies by project type), total cost (hours × effective rate, or liability amount for vendors), margin ($), margin (%)</li><li>Project breakdown within each client</li><li>Revenue calculation follows existing rules per type: T&amp;M = hours × billing rate, Fixed Price = completion % × contract value, Retainer = per-period accrual, Pro Bono = $0, Agile = sprint accrual</li><li>Cost calculation uses the existing P&amp;L cost rule (liability overrides rate × hours)</li><li>Flags clients below a configurable margin threshold</li></ul><p><strong>Permission:</strong> Owner only (dollar amounts). Managers could see a ranked list without dollar values — &quot;Client A is your most profitable, Client D is underwater.&quot;</p><p><strong>Data sources:</strong> <code>02. Projects</code>, <code>04. Clients</code>, <code>01. Time Entries</code>, <code>13. Rate_History</code>, <code>14. Liabilities</code>. All existing.</p><p><strong>Effort:</strong> Medium-high. The revenue recognition logic already exists in <code>generate_monthly_report</code> and <code>get_agile_summary</code> — needs extraction into a shared helper then aggregation at client level.</p><hr><h3 id="_3-real-time-budget-threshold-alerts" tabindex="-1">3. Real-Time Budget Threshold Alerts <a class="header-anchor" href="#_3-real-time-budget-threshold-alerts" aria-label="Permalink to &quot;3. Real-Time Budget Threshold Alerts&quot;">​</a></h3><p><strong>Why third:</strong> The morning summary catches overruns after the fact. A same-day alert when <code>log_time</code> pushes a project past its <code>alert_threshold</code> (default 80%) prevents the damage rather than reporting it.</p><p><strong>What it does:</strong></p><ul><li>After <code>log_time</code> succeeds, check total hours against project budget</li><li>If the entry crossed the threshold: include a <code>threshold_alert</code> in the response and a notification to the PM</li><li>The bot surfaces it inline: &quot;Logged 4h on Nike Campaign. ⚠️ This project is now at 83% of its hour budget — Tom (PM) has been notified.&quot;</li><li>No new endpoint needed — it&#39;s a post-write check inside the existing <code>log_time</code> handler</li></ul><p><strong>Why not first:</strong> Because it&#39;s a write-path change (higher risk, needs careful testing) vs. the two read-only endpoints above.</p><p><strong>Effort:</strong> Low-medium. ~50 lines in <code>log_time</code> handler + notification dispatch.</p><hr><h3 id="_4-invoice-ready-export-—-enhance-get-export-data" tabindex="-1">4. Invoice-Ready Export — enhance <code>get_export_data</code> <a class="header-anchor" href="#_4-invoice-ready-export-—-enhance-get-export-data" aria-label="Permalink to &quot;4. Invoice-Ready Export — enhance `get_export_data`&quot;">​</a></h3><p><strong>Why fourth:</strong> The current export is flat (one row per entry). Agencies need grouped output: Client → Project → Task → date range, with subtotals, optionally with rates. This is the bridge between &quot;time tracked&quot; and &quot;invoice sent.&quot;</p><p><strong>What it does:</strong></p><ul><li>Add <code>group_by</code> param: <code>client</code>, <code>project</code>, <code>task</code> (hierarchical)</li><li>Add <code>date_from</code> / <code>date_to</code> filter</li><li>Add <code>include_rates</code> (owner only) — shows billing rate and line total</li><li>Subtotals at each grouping level</li><li>CSV and JSON output</li></ul><p><strong>Data sources:</strong> Same as current export + <code>02. Projects</code> (billing_rate) + <code>04. Clients</code>.</p><p><strong>Effort:</strong> Low-medium. Extends existing endpoint.</p><hr><h3 id="_5-weekly-digest-—-friday-4pm-cron" tabindex="-1">5. Weekly Digest — Friday 4pm cron <a class="header-anchor" href="#_5-weekly-digest-—-friday-4pm-cron" aria-label="Permalink to &quot;5. Weekly Digest — Friday 4pm cron&quot;">​</a></h3><p><strong>Why fifth:</strong> Mornings are tactical (&quot;what do I need to do today&quot;). A weekly digest is strategic: week-over-week trends, utilization change, revenue pipeline, compliance gaps. This is the &quot;executive briefing&quot; that makes an owner feel the tool is watching the business.</p><p><strong>What it does:</strong></p><ul><li>Fires Friday 4pm (tenant timezone) for owners and managers</li><li><strong>Utilization delta:</strong> team average this week vs last week, who improved, who dropped</li><li><strong>Budget movers:</strong> projects that crossed 50%, 80%, or 100% this week</li><li><strong>Timesheet compliance:</strong> who logged &lt;35h this week (configurable threshold)</li><li><strong>Revenue summary:</strong> total recognized revenue this week by project type (owner only)</li><li><strong>Retainer pulse:</strong> periods expiring in the next 7 days without a successor</li></ul><p><strong>Data sources:</strong> All existing. Compares <code>hours_this_week</code> against same query for previous week (requires a <code>week_start</code> parameter on <code>hours_this_week</code> or a <code>get_time_entries</code> date range query, both of which exist).</p><p><strong>Effort:</strong> Medium. New function in <code>reminders.js</code>, new cron schedule, reuses existing MCP endpoints.</p><hr><h3 id="_6-revenue-forecast-—-get-revenue-forecast" tabindex="-1">6. Revenue Forecast — <code>get_revenue_forecast</code> <a class="header-anchor" href="#_6-revenue-forecast-—-get-revenue-forecast" aria-label="Permalink to &quot;6. Revenue Forecast — `get_revenue_forecast`&quot;">​</a></h3><p><strong>Why last in this phase:</strong> Depends on utilization and client profitability logic being solid. Forecasting is only as good as the calculation it projects forward.</p><p><strong>What it does:</strong></p><ul><li>Input: months ahead (1–6, default 3)</li><li>Per-project forward projection based on type: <ul><li><strong>Retainer:</strong> contract_value × remaining periods in forecast window</li><li><strong>T&amp;M:</strong> trailing 4-week average hours × billing rate × weeks remaining</li><li><strong>Fixed Price:</strong> remaining contract value × projected completion rate</li><li><strong>Agile:</strong> planned sprint values for upcoming sprints</li><li><strong>Pro Bono:</strong> $0</li></ul></li><li>Aggregated by client, by month, by project type</li><li>Confidence indicator: &quot;firm&quot; (contracted retainer) vs &quot;projected&quot; (T&amp;M trend-based)</li><li>Owner only</li></ul><p><strong>Effort:</strong> Medium-high. Needs the revenue recognition helpers from #2, plus trend calculation from time entries.</p><hr><h2 id="what-this-unlocks" tabindex="-1">What This Unlocks <a class="header-anchor" href="#what-this-unlocks" aria-label="Permalink to &quot;What This Unlocks&quot;">​</a></h2><p>After these six additions, VERA answers every question in the owner&#39;s weekly rhythm:</p><table tabindex="0"><thead><tr><th>When</th><th>Question</th><th>Feature</th></tr></thead><tbody><tr><td>Monday morning</td><td>&quot;How utilized was my team last week?&quot;</td><td><code>get_utilization_report</code></td></tr><tr><td>Any time</td><td>&quot;Are we making money on Client X?&quot;</td><td><code>get_client_profitability</code></td></tr><tr><td>After logging</td><td>&quot;Did we blow the budget?&quot;</td><td>Threshold alert (real-time)</td></tr><tr><td>End of month</td><td>&quot;Give me something I can invoice from&quot;</td><td>Enhanced <code>get_export_data</code></td></tr><tr><td>Friday afternoon</td><td>&quot;What should I worry about?&quot;</td><td>Weekly digest</td></tr><tr><td>Board meeting</td><td>&quot;What does next quarter look like?&quot;</td><td><code>get_revenue_forecast</code></td></tr></tbody></table><p>No new database tabs. No schema changes. All read-only except the threshold alert (which piggybacks on existing <code>log_time</code>). Every feature uses data that&#39;s already being written today.</p>',55)])])}const p=t(a,[["render",n]]);export{u as __pageData,p as default};
